          else res.status(404).send('Cannot ' + req.method + ' ' + req.path);
        };
        next();
      });
    },
  };
  return app;
}

export function request(app) {
  const make = (method) => (path) => {
    const req = { method, path, headers: {}, rawBody: null, body: undefined, params: {} };
